INSERT INTO GLOSSARYITEMS (HEADER, DESCRIPTION) VALUES ('Hardware Solution', 'Particularly where the Build Construction is ''Proprietary'' the Equipment manufacture can use the same hardware Platform for mulitple applications with specific vertical integration points. In order to differentiate this it is common for the hardware solution to have the same name as the application running on it. This is therefore a Product Name. TEMS uses the same approach where the Build Construction is COTS. Where the Build Construction is NFVI/NFCI the phrase ''Multiple Applications'' is used.');
