INSERT INTO GLOSSARYITEMS (HEADER, DESCRIPTION) VALUES ('Platform', 'Generally this is static information as changing the platform conmotes modernizing/replacing the solution. The common name used for the collection of compatible hardware brought together in an architecture. Where the hardware is related to NFVI/NFCI TEMS uses the same values as Build Construction; Where the Build Construction is ''Proprietary'' the value represents the name used by the equipment manufacturer for the architectural solution; Where the Build Construction is COTS the model name from the equipment manufacturer is used.');
