INSERT INTO GLOSSARYITEMS (HEADER, DESCRIPTION) VALUES ('Hardware Type', 'Generally this is dynamic information reflecting components that can be life cycle managed. Strictly there are many hardware components that can be upgraded individually and in TEMS we link the value here to the primary component that can be used for scaling also.');
INSERT INTO GLOSSARYITEMS (HEADER, DESCRIPTION) VALUES ('Other Hardware Info', 'A free format text field to add information as seen useful and provide synergy across Opco');
INSERT INTO GLOSSARYITEMS (HEADER, DESCRIPTION) VALUES ('Last Time Buy', 'Towards the end of the product life cycle the manufacturer will announce a last time buy for new deployments. This is the date wanted in this attribute if it has been announced. For existing deployments it is usual that expansions and upgrades are still possible, so the last time buy for upgrades and expansions may be later.');
INSERT INTO GLOSSARYITEMS (HEADER, DESCRIPTION) VALUES ('Last Time Buy upgrades', 'Towards the end of the product life cycle the manufacturer will announce a last time buy for new deployments. For existing deployments it is usual that expansions and upgrades are still possible, so the last time buy for upgrades may be later.  This is the date wanted in this attribute if it has been announced. ');
INSERT INTO GLOSSARYITEMS (HEADER, DESCRIPTION) VALUES ('Last Time Buy Expansions', 'Towards the end of the product life cycle the manufacturer will announce a last time buy for new deployments. For existing deployments it is usual that expansions and upgrades are still possible, so the last time buy for expansions may be later.  This is the date wanted in this attribute if it has been announced. ');
INSERT INTO GLOSSARYITEMS (HEADER, DESCRIPTION) VALUES ('End Of Maintenance', 'Equipment Manufacturer terminology can vary, but the concepts are the same. There is a period of the product life cycle where the manufacturer actively enhances/optimizes the product making patch releases available in a regular way based on in service performance seen around the deployments across different service providers. In TEMS we call this the Maintenance period. At End of Maintenance the Equipment Manufacturer scales down and no longer provides this active engagement. However, for a period of time they will continue to address specific trouble reports from a Service Provider providing patches to that Service Provider as necessary. In TEMS we call this the Support period. After End of Support the Equipment Manufacurer will no longer address trouble reports raised by a Service provider. It is possible for a Service Provider to pay for Extended Support. If this is the case for a specific Opco it will be specified in another part of TEMS.');
INSERT INTO GLOSSARYITEMS (HEADER, DESCRIPTION) VALUES ('End Of Maintenance', 'Equipment Manufacturer terminology can vary, but the concepts are the same. There is a period of the product life cycle where the manufacturer actively enhances/optimizes the product making patch releases available in a regular way based on in service performance seen around the deployments across different service providers. In TEMS we call this the Maintenance period. At End of Maintenance the Equipment Manufacturer scales down and no longer provides this active engagement. However, for a period of time they will continue to address specific trouble reports from a Service Provider providing patches to that Service Provider as necessary. In TEMS we call this the Support period. After End of Support the Equipment Manufacurer will no longer address trouble reports raised by a Service provider. It is possible for a Service Provider to pay for Extended Support. If this is the case for a specific Opco it will be specified in another part of TEMS.');
