INSERT INTO GLOSSARYITEMS (HEADER, DESCRIPTION) VALUES ('Build Construction', 'Within TEMS different hardware solutions are categorized by Build Construction. Proprietary - The OEM provides both the Hardware and the Software solution and there is a strong vertical integration between the two. COTS - Where Commercial Off The Shelf equipment is used the vertical integration between software and hardware uses standard APIs so the equipment manufacturers are fully decoupled. Typically it is used with specific solutions where Vodafone '||'('||'perhaps in conjunction with a third party'||')'||' have integrated application, middleware and operating system with a COTS hardware solution such as an HP Proliant solution. Voice Core remain responsible for the asset and its life cycle management. Blueprint NFVI/NFCI - A Virtual/Container infrastructure following a Vodafone Defined blueprint architecture and representing a strategic deployment. It hosts multiple applications. The Infrastructure team '||'('||'Not Voice Core'||')'||' are responsible for the asset and its life cycle management. Other NFVI/NFCI - A Virtual/Container infrastructure following deployed before the  blueprint architecture solutions were available. They are not strategic deployment and are being phased out - for example Cisco V-Block. It hosts multiple applications. The Infrastructure team '||'('||'Not Voice Core'||')'||' are responsible for the asset and its life cycle management.');
